#include "FlightBoardWiFi.h"
#include <stdexcept>
static int assertions=0;
#define CHECK(expr) do { ++assertions; if(!(expr)) throw std::runtime_error(std::string(__func__)+":"+std::to_string(__LINE__)+": " #expr); } while(0)
void reset(){testNow=1000;WiFi=WiFiMock();MDNS=MdnsMock();Preferences::values.clear();Preferences::writes.clear();Preferences::available=true;Preferences::failStationWrite=false;Serial.reset();scanStops=0;}
JsonDocument response(WebServer&s){JsonDocument d;CHECK(!deserializeJson(d,s.responseBody));return d;}
JsonDocument stored(){JsonDocument d;CHECK(!deserializeJson(d,Preferences::values["station"]));return d;}
void seed(const char*ssid="Previous",const char*password="previous-pass"){JsonDocument d;d["ssid"]=ssid;d["password"]=password;String json;serializeJson(d,json);Preferences::values["station"]=json;}
String candidate(const String&ssid="Candidate",const String&password="candidate-pass",bool open=false){JsonDocument d;d["ssid"]=ssid;d["password"]=password;d["open"]=open;String json;serializeJson(d,json);return json;}
int stationWrites(){int n=0;for(auto&w:Preferences::writes)if(w.first=="station")++n;return n;}
void test_no_credentials(){reset();WebServer s;FlightBoardWiFi wifi(s);wifi.begin("REMPLACER_SSID","REMPLACER_PASSWORD");CHECK(wifi.rescueActive());CHECK(WiFi.modeValue==WIFI_AP_STA);CHECK(WiFi.apStartCalls==1);CHECK(WiFi.beginCalls==0);CHECK(!wifi.update());CHECK(!wifi.allowsRadar());s.request("/api/wifi");auto d=response(s);CHECK(d["state"]=="unconfigured");CHECK(d["apActive"]==true);CHECK(d["apPassword"].as<String>().length()==16);CHECK(!d["password"].is<String>());CHECK(s.headers["Cache-Control"]=="no-store");CHECK(stationWrites()==0);}
void test_boot_timeout_retry_and_success(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);CHECK(!wifi.rescueActive());CHECK(WiFi.lastBeginSsid=="Previous");CHECK(WiFi.lastBeginPassword=="previous-pass");testNow+=24999;CHECK(!wifi.update());CHECK(!wifi.rescueActive());testNow+=1;CHECK(!wifi.update());CHECK(wifi.rescueActive());CHECK(WiFi.beginCalls==1);testNow+=29999;wifi.update();CHECK(WiFi.beginCalls==1);testNow+=1;wifi.update();CHECK(WiFi.beginCalls==2);WiFi.connect("Previous");CHECK(wifi.update());CHECK(!wifi.update());CHECK(wifi.allowsRadar());CHECK(MDNS.starts==1);CHECK(stationWrites()==0);CHECK(Serial.output.str().find("previous-pass")==std::string::npos);}
void test_candidate_deferred_save_and_idle_ap(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);WiFi.connect("Previous");CHECK(wifi.update());s.request("/api/wifi",HTTP_POST,candidate());CHECK(s.responseCode==202);auto d=response(s);CHECK(d["pendingSsid"]=="Candidate");CHECK(d["state"]=="connecting");CHECK(wifi.rescueActive());CHECK(stationWrites()==0);CHECK(!wifi.allowsRadar());CHECK(std::string(s.responseBody.c_str()).find("candidate-pass")==std::string::npos);CHECK(std::string(s.responseBody.c_str()).find("previous-pass")==std::string::npos);int begins=WiFi.beginCalls;testNow+=1199;wifi.update();CHECK(WiFi.beginCalls==begins);testNow+=1;wifi.update();CHECK(WiFi.beginCalls==begins+1);CHECK(WiFi.lastBeginSsid=="Candidate");CHECK(stationWrites()==0);WiFi.connect("Previous");wifi.update();CHECK(stationWrites()==0);WiFi.connect("Candidate");CHECK(wifi.update());CHECK(stationWrites()==1);auto saved=stored();CHECK(saved["ssid"]=="Candidate");CHECK(saved["password"]=="candidate-pass");CHECK(!wifi.update());testNow+=8799;CHECK(!wifi.allowsRadar());testNow+=1;CHECK(wifi.allowsRadar());testNow+=51200;wifi.update();CHECK(!wifi.rescueActive());CHECK(WiFi.apStopCalls==1);}
void test_failed_candidate_restores_previous(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);WiFi.connect("Previous");wifi.update();s.request("/api/wifi",HTTP_POST,candidate());testNow+=1200;wifi.update();testNow+=25000;wifi.update();CHECK(stationWrites()==0);auto saved=stored();CHECK(saved["ssid"]=="Previous");CHECK(wifi.rescueActive());s.request("/api/wifi");auto d=response(s);CHECK(d["state"]=="failed");CHECK(d["pendingSsid"]=="");testNow+=1999;wifi.update();CHECK(WiFi.lastBeginSsid=="Candidate");testNow+=1;wifi.update();CHECK(WiFi.lastBeginSsid=="Previous");WiFi.connect("Previous");CHECK(wifi.update());s.request("/api/wifi");d=response(s);CHECK(d["connected"]==true);CHECK(d["state"]=="failed");CHECK(d["ssid"]=="Previous");}
void test_failed_flash_retains_previous(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);WiFi.connect("Previous");wifi.update();s.request("/api/wifi",HTTP_POST,candidate());testNow+=1200;wifi.update();Preferences::failStationWrite=true;WiFi.connect("Candidate");CHECK(!wifi.update());CHECK(stationWrites()==0);CHECK(stored()["ssid"]=="Previous");CHECK(WiFi.status()!=WL_CONNECTED);testNow+=2000;wifi.update();CHECK(WiFi.lastBeginSsid=="Previous");}
void test_scans_and_concurrency(){reset();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);s.request("/api/wifi/scan");CHECK(s.responseCode==200);CHECK(response(s)["scanning"]==true);CHECK(WiFi.scanCalls==1);s.request("/api/wifi/scan");CHECK(WiFi.scanCalls==1);s.request("/api/wifi",HTTP_POST,candidate());CHECK(s.responseCode==409);WiFi.networks={{"Weak",-85,3},{"Strong",-30,3},{"Weak",-50,3},{"",-10,3},{WiFi.apSsid,-15,3},{"Strong",-40,WIFI_AUTH_OPEN}};WiFi.scanCompleteResult=WiFi.networks.size();wifi.update();s.request("/api/wifi/scan");CHECK(WiFi.scanCalls==1);auto d=response(s);CHECK(d["scanning"]==false);CHECK(d["networks"].size()==3);CHECK(d["networks"][0]["ssid"]=="Strong");CHECK(d["networks"][0]["open"]==false);CHECK(d["networks"][1]["open"]==true);CHECK(d["networks"][2]["rssi"]==-50);s.request("/api/wifi/scan",HTTP_GET,"",true);CHECK(WiFi.scanCalls==2);testNow+=15000;wifi.update();CHECK(scanStops==1);s.request("/api/wifi/scan");d=response(s);CHECK(d["scanning"]==false);CHECK(d["error"].is<String>());CHECK(WiFi.scanCalls==2);WiFi.scanStartResult=WIFI_SCAN_FAILED;s.request("/api/wifi/scan",HTTP_GET,"",true);CHECK(response(s)["error"].is<String>());CHECK(WiFi.scanCalls==3);s.request("/api/wifi",HTTP_POST,candidate());CHECK(s.responseCode==202);s.request("/api/wifi/scan");CHECK(s.responseCode==409);s.request("/api/wifi",HTTP_POST,candidate());CHECK(s.responseCode==409);}
void test_scan_limit_and_empty(){reset();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);s.request("/api/wifi/scan");for(int i=0;i<25;++i)WiFi.networks.push_back({String("Network"+std::to_string(i)),-40-i,3});WiFi.scanCompleteResult=25;wifi.update();s.request("/api/wifi/scan");CHECK(response(s)["networks"].size()==20);s.request("/api/wifi/scan",HTTP_GET,"",true);WiFi.scanCompleteResult=0;wifi.update();s.request("/api/wifi/scan");auto d=response(s);CHECK(d["networks"].size()==0);CHECK(!d["error"].is<String>());}
void validate(const String&body,int code){reset();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);s.request("/api/wifi",HTTP_POST,body);CHECK(s.responseCode==code);CHECK(stationWrites()==0);}
void test_validation(){validate("",400);validate("{",400);validate("[]",400);validate("{}",400);validate("{\"ssid\":12,\"password\":\"password\",\"open\":false}",400);validate("{\"ssid\":\"Test\",\"password\":\"password\",\"open\":\"false\"}",400);validate(candidate("","password"),400);validate(candidate(std::string(33,'s'),"password"),400);validate(candidate(std::string(32,'s'),"password"),202);validate(candidate("Test","short"),400);validate(candidate("Test",std::string(63,'p')),202);validate(candidate("Test",std::string(64,'a')),202);validate(candidate("Test",std::string(64,'z')),400);validate(candidate("Test",std::string(65,'a')),400);validate(candidate("Open","",true),202);validate(candidate("Open","",false),400);validate(candidate("Open","password",true),400);validate("{\"ssid\":\"Abc\\u0000def\",\"password\":\"password\",\"open\":false}",400);validate("{\"ssid\":\"Abc\",\"password\":\"pass\\u0000word\",\"open\":false}",400);validate(candidate(std::string(32,'s'),std::string(500,'p')),400);}
void test_storage_unavailable_and_ap_failure(){reset();Preferences::available=false;WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);CHECK(wifi.rescueActive());s.request("/api/wifi",HTTP_POST,candidate());CHECK(s.responseCode==503);reset();WiFi.apSuccess=false;WebServer s2;FlightBoardWiFi wifi2(s2);wifi2.begin(nullptr,nullptr);CHECK(!wifi2.rescueActive());CHECK(WiFi.apStartCalls==1);testNow+=9999;wifi2.update();CHECK(WiFi.apStartCalls==1);testNow+=1;wifi2.update();CHECK(WiFi.apStartCalls==2);s2.request("/api/wifi",HTTP_POST,candidate());CHECK(s2.responseCode==503);CHECK(WiFi.beginCalls==0);}
void test_lost_connection_and_wrap(){reset();seed();testNow=ULONG_MAX-1000;WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);testNow+=24999;wifi.update();CHECK(!wifi.rescueActive());testNow+=1;wifi.update();CHECK(wifi.rescueActive());testNow+=2000;wifi.update();WiFi.connect("Previous");CHECK(wifi.update());WiFi.disconnect();wifi.update();CHECK(wifi.rescueActive());CHECK(MDNS.stops>=1);testNow+=30000;wifi.update();CHECK(WiFi.lastBeginSsid=="Previous");WiFi.connect("Previous");CHECK(wifi.update());CHECK(!wifi.update());}
void test_keepalive_does_not_prevent_rollback(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);WiFi.connect("Previous");wifi.update();s.request("/api/wifi",HTTP_POST,candidate());testNow+=1200;wifi.update();testNow+=25000;wifi.update();for(int i=0;i<4;++i){testNow+=500;s.request("/api/wifi/keepalive");CHECK(s.responseCode==200);wifi.update();}CHECK(WiFi.lastBeginSsid=="Previous");CHECK(stationWrites()==0);}
void test_defaults_and_corrupt_storage(){reset();Preferences::values["station"]="invalid json";WebServer s;FlightBoardWiFi wifi(s);wifi.begin("DefaultNetwork","default-pass");CHECK(WiFi.lastBeginSsid=="DefaultNetwork");CHECK(stationWrites()==0);reset();Preferences::values["station"]="{\"ssid\":\"Bad\",\"password\":\"short\"}";WebServer s2;FlightBoardWiFi wifi2(s2);wifi2.begin(nullptr,nullptr);CHECK(wifi2.rescueActive());CHECK(WiFi.beginCalls==0);}
void test_portal_background_recovery_and_interruptions(){reset();seed();WebServer s;FlightBoardWiFi wifi(s);wifi.begin(nullptr,nullptr);testNow+=25000;wifi.update();CHECK(wifi.rescueActive());for(int i=0;i<6;++i){testNow+=5000;s.request("/api/wifi/keepalive");wifi.update();}CHECK(WiFi.beginCalls==2);CHECK(WiFi.lastBeginSsid=="Previous");CHECK(!wifi.allowsRadar());WiFi.connect("Previous");CHECK(wifi.update());s.request("/api/wifi");CHECK(response(s)["connected"]==true);CHECK(response(s)["state"]=="connected");reset();seed();WebServer s2;FlightBoardWiFi wifi2(s2);wifi2.begin(nullptr,nullptr);s2.request("/api/wifi/scan");CHECK(s2.responseCode==200);CHECK(response(s2)["scanning"]==true);WiFi.scanCompleteResult=0;wifi2.update();s2.request("/api/wifi",HTTP_POST,candidate());CHECK(s2.responseCode==202);testNow+=1200;wifi2.update();CHECK(WiFi.lastBeginSsid=="Candidate");reset();seed();WebServer s3;FlightBoardWiFi wifi3(s3);wifi3.begin(nullptr,nullptr);s3.request("/api/wifi",HTTP_POST,candidate());CHECK(s3.responseCode==202);CHECK(WiFi.lastBeginSsid=="Previous");testNow+=1200;wifi3.update();CHECK(WiFi.lastBeginSsid=="Candidate");}
int main(){const std::vector<std::pair<const char*,std::function<void()>>>tests={{"unconfigured boot",test_no_credentials},{"saved boot timeout and retry",test_boot_timeout_retry_and_success},{"candidate deferred/save/AP idle",test_candidate_deferred_save_and_idle_ap},{"failed candidate rollback",test_failed_candidate_restores_previous},{"flash failure rollback",test_failed_flash_retains_previous},{"scans cache/concurrency/failure",test_scans_and_concurrency},{"scan limits/empty",test_scan_limit_and_empty},{"credential validation",test_validation},{"storage/AP failures",test_storage_unavailable_and_ap_failure},{"network loss/unsigned timer wrap",test_lost_connection_and_wrap},{"keepalive permits rollback",test_keepalive_does_not_prevent_rollback},{"defaults/corrupt storage",test_defaults_and_corrupt_storage},{"portal background recovery and cancellation",test_portal_background_recovery_and_interruptions}};int failed=0;for(auto&t:tests){try{t.second();std::cout<<"PASS "<<t.first<<'\n';}catch(const std::exception&e){++failed;std::cerr<<"FAIL "<<t.first<<": "<<e.what()<<'\n';}}std::cout<<tests.size()<<" scenarios, "<<assertions<<" assertions, "<<failed<<" failed\n";return failed?1:0;}
